from collections import defaultdict

def shortest_path(graph, source, target):
    def heap_to_path(edges_heap, graph, path):
        while edges_heap:
            edge = heapq.heappop(edges_heap)
            node, weight = edge[1], edge[0]
            if node in graph:
                path.append(node)
                graph[node].remove((node, weight))
                if not graph[node]:
